/* generic drag helper: drag an element, drop on [data-drop] targets */
function draggable(el, { onDrop, onTap, ghostClass = 'drag' }) {
  el.addEventListener('pointerdown', e => {
    e.preventDefault(); const p0 = pt(e); let moved = false; const r0 = el.getBoundingClientRect();
    el.setPointerCapture(e.pointerId); el.classList.add(ghostClass);
    const move = ev => { const p = pt(ev); const dx = p.x - p0.x, dy = p.y - p0.y; if (Math.hypot(dx, dy) > 8) moved = true; el.style.transform = `translate(${dx}px,${dy}px)`;
      $$('[data-drop]').forEach(d => d.classList.toggle('hot', hit(d, ev))); };
    const up = ev => { el.removeEventListener('pointermove', move); el.removeEventListener('pointerup', up); el.removeEventListener('pointercancel', up);
      el.classList.remove(ghostClass); el.style.transform = ''; const tgt = $$('[data-drop]').find(d => hit(d, ev)); $$('[data-drop]').forEach(d => d.classList.remove('hot'));
      if (!moved) { onTap && onTap(); return; } if (tgt) onDrop(tgt); };
    el.addEventListener('pointermove', move); el.addEventListener('pointerup', up); el.addEventListener('pointercancel', up);
  });
}
const hit = (d, ev) => { const r = d.getBoundingClientRect(); return ev.clientX >= r.left && ev.clientX <= r.right && ev.clientY >= r.top && ev.clientY <= r.bottom; };

const RUN = {};

/* ===== 1. Puzzle: drag pieces into place ===== */
RUN.puzzle = api => {
  const ART = [
    { n: 3, name: 'صورة', msg: 'لا تشارك رمز التحقق', svg: m => `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 600 600'><rect width='600' height='600' fill='#173B3A'/><g stroke='#84B6C6' stroke-width='4' opacity='.55'><line x1='80' y1='90' x2='300' y2='300'/><line x1='520' y1='90' x2='300' y2='300'/><line x1='80' y1='470' x2='300' y2='300'/><line x1='520' y1='470' x2='300' y2='300'/><line x1='80' y1='90' x2='520' y2='90'/></g><g fill='#84B6C6'><circle cx='80' cy='90' r='24'/><circle cx='520' cy='90' r='24'/><circle cx='80' cy='470' r='24'/><circle cx='520' cy='470' r='24'/></g><path d='M300 160 L400 200 V290 C400 360 350 400 300 420 C250 400 200 360 200 290 V200 Z' fill='#C9705F'/><rect x='262' y='270' width='76' height='62' rx='10' fill='#F4F2EA'/><path d='M276 270 v-18 a24 24 0 0 1 48 0 v18' stroke='#F4F2EA' stroke-width='10' fill='none'/><text x='300' y='550' font-family='Tajawal,sans-serif' font-size='44' font-weight='800' fill='#F4F2EA' text-anchor='middle'>${m}</text></svg>` },
    { n: 3, name: 'شبكة', msg: 'افصل الجهاز المصاب', svg: m => `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 600 600'><rect width='600' height='600' fill='#12302F'/><g stroke='#84B6C6' stroke-width='5' opacity='.7'><line x1='300' y1='120' x2='120' y2='300'/><line x1='300' y1='120' x2='480' y2='300'/><line x1='120' y1='300' x2='300' y2='440'/><line x1='480' y1='300' x2='300' y2='440'/></g><line x1='300' y1='120' x2='300' y2='440' stroke='#E07A6A' stroke-width='5' stroke-dasharray='14 10'/><rect x='250' y='75' width='100' height='90' rx='14' fill='#C9705F'/><circle cx='120' cy='300' r='44' fill='#1F4644' stroke='#84B6C6' stroke-width='5'/><circle cx='480' cy='300' r='44' fill='#1F4644' stroke='#84B6C6' stroke-width='5'/><circle cx='300' cy='440' r='44' fill='#5A2A24' stroke='#E07A6A' stroke-width='5'/><path d='M282 425 l36 30 M318 425 l-36 30' stroke='#F4F2EA' stroke-width='7'/><text x='300' y='550' font-family='Tajawal,sans-serif' font-size='44' font-weight='800' fill='#F4F2EA' text-anchor='middle'>${m}</text></svg>` },
    { n: 4, name: 'نظام حماية', msg: 'فعّل التحقق الثنائي', svg: m => `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 600 600'><rect width='600' height='600' fill='#173B3A'/><g fill='none' stroke='#84B6C6' stroke-width='6'><circle cx='300' cy='270' r='200' opacity='.35'/><circle cx='300' cy='270' r='150' opacity='.6'/></g><rect x='200' y='170' width='200' height='200' rx='26' fill='#B95D4E'/><circle cx='300' cy='245' r='30' fill='#F4F2EA'/><rect x='290' y='262' width='20' height='60' rx='8' fill='#F4F2EA'/><g font-family='monospace' font-size='38' fill='#F4F2EA'><text x='80' y='120'>●●●</text><text x='420' y='120'>482</text></g><text x='300' y='550' font-family='Tajawal,sans-serif' font-size='44' font-weight='800' fill='#F4F2EA' text-anchor='middle'>${m}</text></svg>` },
  ];
  let lv = 0, placed = 0;
  const run = () => {
    const a = ART[lv], n = a.n, cell = 600 / n, url = 'data:image/svg+xml;utf8,' + encodeURIComponent(a.svg(a.msg));
    placed = 0;
    const spots = shuffle([...Array(24)].map((_, i) => i < 12 ? [90 + (i % 3) * 180, 220 + Math.floor(i / 3) * 175] : [1330 + ((i - 12) % 3) * 170, 640 + Math.floor((i - 12) / 3) * 105]));
    api.el.innerHTML = `<div class="card side" style="top:220px;right:64px;width:440px"><h2>رتّب القطع</h2><p>اسحب كل قطعة إلى مكانها لتكتشف الرسالة الأمنية المخفية خلف الشبكة.</p>
      <div class="lv">${ART.map((x, k) => `<span class="${k === lv ? 'on' : k < lv ? 'done' : ''}">${x.name}</span>`).join('')}</div></div>
      <div class="board" id="bd">${[...Array(n * n)].map((_, i) => `<div class="cellg" style="left:${(i % n) * cell}px;top:${Math.floor(i / n) * cell}px;width:${cell}px;height:${cell}px"></div>`).join('')}</div>
      <div class="abs" style="bottom:70px;left:660px;width:600px;text-align:center;font-size:24px"><span id="pg">0 من ${n * n} قطعة في مكانها</span><div class="bar" style="margin-top:14px"><i id="pb" style="width:0"></i></div></div>`;
    for (let i = 0; i < n * n; i++) {
      const p = document.createElement('button'); p.className = 'pc'; p.setAttribute('aria-label', 'قطعة');
      const sp = spots[i % spots.length], size = Math.min(cell, 150);
      Object.assign(p.style, { width: cell + 'px', height: cell + 'px', left: sp[0] + 'px', top: sp[1] + 'px', backgroundImage: `url("${url}")`, backgroundSize: '600px 600px', backgroundPosition: `-${(i % n) * cell}px -${Math.floor(i / n) * cell}px`, transform: `rotate(${(Math.random() * 20 - 10).toFixed(1)}deg)` });
      p.dataset.r = (Math.random() * 20 - 10).toFixed(1);
      api.el.appendChild(p);
      p.addEventListener('pointerdown', e => {
        if (p.classList.contains('lock')) return; e.preventDefault();
        const p0 = pt(e), l0 = parseFloat(p.style.left), t0 = parseFloat(p.style.top);
        p.setPointerCapture(e.pointerId); p.classList.add('drag'); p.style.transform = 'none'; api.el.appendChild(p);
        const mv = ev => { const q = pt(ev); p.style.left = l0 + q.x - p0.x + 'px'; p.style.top = t0 + q.y - p0.y + 'px'; };
        const up = () => {
          p.removeEventListener('pointermove', mv); p.removeEventListener('pointerup', up); p.classList.remove('drag');
          const tx = 660 + (i % n) * cell, ty = 220 + Math.floor(i / n) * cell;
          if (Math.hypot(parseFloat(p.style.left) - tx, parseFloat(p.style.top) - ty) < cell * 0.45) {
            p.style.left = tx + 'px'; p.style.top = ty + 'px'; p.classList.add('lock'); placed++; api.add(Math.round(330 / (n * n)));
            $('#pg').textContent = `${placed} من ${n * n} قطعة في مكانها`; $('#pb').style.width = placed / (n * n) * 100 + '%';
            if (placed === n * n) { toast('انكشفت الرسالة: «' + a.msg + '»'); setTimeout(() => { lv++; if (lv < ART.length) run(); else { api.add(S.left); api.end({ detail: 'أكملت المستويات الثلاثة' }); } }, 1500); }
          } else p.style.transform = `rotate(${p.dataset.r}deg)`;
        };
        p.addEventListener('pointermove', mv); p.addEventListener('pointerup', up);
      });
    }
  };
  api.onTimeout = () => api.end({ timeout: true, detail: `أكملت ${lv} من 3 مستويات` });
  run();
};

/* ===== 2. Network: draw safe paths with the finger ===== */
RUN.network = api => {
  const N = { S: [1560, 400, 'srv'], A: [1180, 230, 'sus'], B: [1180, 400, 'sus'], C: [1180, 600, 'bad'], D: [760, 230, 'n'], E: [760, 400, 'bad'], F: [760, 600, 'n'], P1: [300, 180, 'dev'], P2: [300, 400, 'dev'], P3: [300, 620, 'dev'] };
  const E = [['P1', 'D'], ['P2', 'D'], ['P2', 'E'], ['P2', 'F'], ['P3', 'F'], ['D', 'A'], ['D', 'B'], ['D', 'E'], ['E', 'B'], ['E', 'F'], ['F', 'B'], ['F', 'C'], ['A', 'S'], ['B', 'S'], ['C', 'S'], ['A', 'B'], ['B', 'C']];
  const adj = (a, b) => E.some(([x, y]) => (x === a && y === b) || (x === b && y === a));
  let fw = new Set(), fwLeft = 2, path = [], links = {}, drawing = false;
  const done = () => Object.keys(links).length;
  const col = k => { const t = N[k][2]; return t === 'bad' ? '#E07A6A' : t === 'sus' ? (fw.has(k) ? '#6FBF9A' : '#E8C77A') : t === 'srv' ? '#C9705F' : '#84B6C6'; };
  const icn = k => { const t = N[k][2]; return t === 'dev' ? 'Laptop' : t === 'srv' ? 'Server' : t === 'bad' ? 'Skull' : t === 'sus' ? (fw.has(k) ? 'BrickWall' : 'ShieldAlert') : 'Network'; };
  const draw = () => {
    const seg = p => new Set(p.slice(0, -1).map((n, i) => [n, p[i + 1]].sort().join('-')));
    const used = new Set(Object.values(links).flatMap(p => [...seg(p)])), cur = seg(path);
    api.el.innerHTML = `<svg class="nsvg" viewBox="0 0 1800 820" id="nv">${E.map(([a, b]) => { const k = [a, b].sort().join('-'); const u = used.has(k), c = cur.has(k);
      const bad = N[a][2] === 'bad' || N[b][2] === 'bad';
      return `<line x1="${N[a][0]}" y1="${N[a][1]}" x2="${N[b][0]}" y2="${N[b][1]}" stroke="${u ? '#6FBF9A' : c ? '#F4F2EA' : bad ? '#E07A6A' : 'rgba(244,242,234,.18)'}" stroke-width="${u ? 10 : c ? 8 : 4}" ${bad && !u ? 'stroke-dasharray="12 10" opacity=".6"' : ''} stroke-linecap="round"/>`; }).join('')}
      ${Object.keys(N).map(k => { const [x, y, t] = N[k], r = t === 'srv' ? 85 : 60, act = path.includes(k);
        return `<g data-n="${k}" style="cursor:pointer"><circle cx="${x}" cy="${y}" r="${r}" fill="${act ? '#21504E' : '#123534'}" stroke="${col(k)}" stroke-width="${act ? 7 : 4}" ${t === 'bad' ? 'fill-opacity=".9"' : ''}/>
        <g transform="translate(${x - (t === 'srv' ? 36 : 26)} ${y - (t === 'srv' ? 36 : 26)}) scale(${t === 'srv' ? 3 : 2.17})" stroke="${col(k)}" fill="none" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${inner(icn(k))}</g>
        ${t === 'dev' ? `<text x="${x}" y="${y + r + 34}" fill="${links[k] ? '#6FBF9A' : '#C7D3D1'}" font-size="24" text-anchor="middle" font-family="Tajawal">${links[k] ? 'متصل ✓' : 'جهاز ' + k.slice(1)}</text>` : ''}
        ${t === 'srv' ? `<text x="${x}" y="${y + r + 36}" fill="#F4F2EA" font-size="26" text-anchor="middle" font-family="Tajawal">الخادم</text>` : ''}</g>`; }).join('')}</svg>
      <div class="legend"><span><i style="background:var(--ok)"></i>مسار آمن</span><span><i style="background:var(--bad)"></i>عقدة مصابة</span><span><i style="background:var(--gold)"></i>عقدة مشبوهة</span><span><i style="background:var(--terr)"></i>جدار حماية</span></div>
      <div class="card abs" style="bottom:40px;left:64px;display:flex;gap:16px;align-items:center;padding:18px 26px;font-size:24px"><span style="color:var(--coral)">${I('BrickWall')}</span> جدران الحماية المتبقية: <b>${fwLeft}</b> · المس عقدة صفراء لعزلها</div>
      <div class="card abs" style="top:150px;right:64px;padding:16px 24px;font-size:24px">الأجهزة المتصلة: <b>${done()} من 3</b></div>
      <div class="abs muted" style="top:160px;left:64px;font-size:22px;max-width:700px">اسحب بإصبعك من جهاز عبر العُقد حتى الخادم</div>`;
    const sv = $('#nv');
    const nodeAt = ev => { const el = document.elementFromPoint(ev.clientX, ev.clientY); const g = el && el.closest('[data-n]'); return g ? g.dataset.n : null; };
    sv.addEventListener('pointerdown', ev => { const k = nodeAt(ev); if (!k) return; ev.preventDefault();
      if (N[k][2] === 'sus' && !fw.has(k)) { if (!fwLeft) return toast('انتهت جدران الحماية'); fw.add(k); fwLeft--; toast('وُضع جدار حماية'); return draw(); }
      if (N[k][2] !== 'dev') return toast('ابدأ المسار من جهاز');
      if (links[k]) return toast('هذا الجهاز متصل بالفعل');
      path = [k]; drawing = true; sv.setPointerCapture(ev.pointerId); draw(); });
    sv.addEventListener('pointermove', ev => { if (!drawing) return; const k = nodeAt(ev); if (k) step(k); });
    sv.addEventListener('pointerup', () => { drawing = false; });
  };
  const step = k => {
    const last = path[path.length - 1]; if (k === last || path.includes(k) || !adj(last, k)) return;
    const t = N[k][2];
    if (t === 'bad') { api.add(-100); path = []; drawing = false; toast('عقدة مصابة! −100 وبدأ المسار من جديد'); return draw(); }
    if (t === 'sus' && !fw.has(k)) { drawing = false; path = []; toast('عقدة مشبوهة: المسها لوضع جدار حماية أولًا'); return draw(); }
    path.push(k);
    if (t === 'srv') { links[path[0]] = path.slice(); path = []; drawing = false; api.add(280);
      if (done() === 3) { api.add(Math.min(160, S.left) + fwLeft * 20); draw(); return setTimeout(() => api.end({ detail: 'وصّلت الأجهزة الثلاثة بأمان' }), 700); } }
    draw();
  };
  api.onTimeout = () => api.end({ timeout: true, detail: `وصّلت ${done()} من 3 أجهزة` });
  draw();
};

